"""地理2：日本の姿（地理ワーク p10〜11・14〜17・28〜29・74〜75）"""
from soc import geo, T, C, SEQ, N, S, R

def nihon():
    u = geo('nihon', '日本の位置・領域と都道府県', {10, 11, 14, 15, 16, 17, 28, 29, 74, 75},
            '2026-10-07 Claude作成。地理ワークp10〜11（日本の位置・日本の領域・領土をめぐる問題）、p14〜15（地理の補強 都道府県の名前と位置・県庁所在地）、p16〜17（重要資料・確かめ問題）、p28〜29（書きトレ）、p74〜75（重要用語マスター）を写真で確認し、問い方・数値を変えて作り直した。手書きの答えは使っていない。')
    q = u.q
    q(10, '①', '日本の位置', '日本は、およそ北緯何度から何度の間に位置しているか。次から選ぼう。\nア 北緯0度〜20度　イ 北緯20度〜50度　ウ 北緯50度〜70度', T('イ'), '日本はおよそ北緯20度から50度の間にある。', near=['ア', 'ウ'])
    q(10, '①', '日本の位置', '日本は、およそ東経何度から何度の間に位置しているか。次から選ぼう。\nア 東経0度〜30度　イ 東経120度〜155度　ウ 西経120度〜155度', T('イ'), '日本はおよそ東経120度から155度の間。', near=['ア', 'ウ'])
    q(10, '①', '日本の位置', '日本は、何という大陸の東にある島国か。', T('ユーラシア大陸', 'ユーラシア'), '日本はユーラシア大陸の東にあり、太平洋の北西部にある島国。', near=['北アメリカ大陸', 'オーストラリア大陸'])
    q(10, '①', '日本の位置', '日本は、どの大洋の北西部にある島国と説明できるか。', T('太平洋', 'たいへいよう'), '太平洋の北西部。', near=['大西洋', 'インド洋'])
    q(16, 'D①(2)', '日本の位置', '韓国から見た日本の位置を、海洋の名称と方位を使って説明しよう。', R((1, ['日本海']), (1, ['東'])), '韓国から見ると、日本は日本海をはさんで東にある。', example='日本海をはさんで東にある。')
    q(11, 'B①(1)', '日本の位置', '日本とほぼ同じ緯度にある国を、次から1つ選ぼう。\nア オーストラリア　イ エジプト　ウ ノルウェー　エ ブラジル', T('イ'), 'エジプト（カイロは北緯30度付近）は日本の南部とほぼ同じ緯度。', near=['ア', 'ウ'])
    q(11, 'B①(1)', '日本の位置', '日本とほぼ同じ経度にある国を、次から1つ選ぼう。\nア オーストラリア　イ エジプト　ウ ノルウェー　エ ブラジル', T('ア'), 'オーストラリアは日本のほぼ真南にあり、経度がほぼ同じ。', near=['イ', 'エ'])
    # 領域
    q(10, '③', '日本の領域', '日本の国土は、北海道・本州・四国・九州の4つの大きな島と何から成り立っているか。', R((1, ['島'])), '4つの大きな島と、その周辺の大小さまざまな島々から成り立つ。', example='周辺の大小さまざまな島々')
    q(10, '③', '日本の領域', '日本の4つの大きな島のうち、最も面積が大きい島はどれか。', T('本州', 'ほんしゅう'), '本州。', near=['北海道', '九州'])
    q(10, '③', '日本の領域', '北海道・本州・四国・九州のうち、本州の次に面積が大きい島はどれか。', T('北海道', 'ほっかいどう'), '面積は本州＞北海道＞九州＞四国の順。', near=['九州', '四国'])
    q(10, '③', '日本の領域', '日本列島は、北海道から沖縄まで約何kmにわたってのびているか。次から選ぼう。\nア 約300km　イ 約3000km　ウ 約30000km', T('イ'), '約3000kmにわたって弓なりにのびる。', near=['ア', 'ウ'])
    q(10, '③', '領域', '国の主権がおよぶ範囲である「領域」は、領土・領海と、もう1つ何から成り立つか。', T('領空', 'りょうくう'), '領域＝領土・領海・領空。', near=['排他的経済水域'])
    q(75, '⑦', '領空', '領空とは、どのような範囲の空か。', R((1, ['領土']), (1, ['領海']), (1, ['上空', '上の空'])), '領空は、領土と領海の上空（大気圏内）。', example='領土と領海の上空。')
    q(10, '③', '領海', '日本の領海は、沿岸から何海里以内の海域か。', N(12, ['海里']), '領海は沿岸から12海里（約22km）以内。', near=['24', '200'])
    q(10, '③', '接続水域', '領海の外側で、沿岸から24海里以内の海域を何というか。', T('接続水域', 'せつぞくすいいき'), '接続水域。', near=['排他的経済水域', '領海'])
    q(10, '③', '排他的経済水域', '領海の外側で、沿岸から200海里以内の海域を何というか。', T('排他的経済水域', 'はいたてきけいざいすいいき', 'EEZ', '排他的経済水域（EEZ）'), '排他的経済水域では、沿岸国が水産資源や鉱産資源を利用する権利をもつ。', near=['接続水域', '公海'])
    q(10, '③', '排他的経済水域', '200海里はおよそ何kmか。次から選ぼう。\nア 約22km　イ 約370km　ウ 約2000km', T('イ'), '1海里は約1852m。200海里≒約370km。', near=['ア', 'ウ'])
    q(28, 'その①(4)', '排他的経済水域', '排他的経済水域とは、どのような海域か。「水産資源や鉱産資源」「権利」という語句を使って書こう。', R((1, ['水産資源']), (1, ['鉱産資源']), (1, ['権利']), (1, ['沿岸国', '沿岸の国', 'その国'])), '沿岸の国が水産資源や鉱産資源を利用する権利をもつ海域。', example='沿岸の国が水産資源や鉱産資源を利用する権利をもつ海域。')
