    q(11, 'B②(3)', '排他的経済水域', '日本の国土面積は約38万km²だが、領海と排他的経済水域を合わせた面積は約何万km²か。次から選ぼう。\nア 約45万km²　イ 約447万km²　ウ 約4470万km²', T('イ'), '約447万km²で、国土面積の10倍以上。', near=['ア', 'ウ'])
    q(17, 'D②(1)', '排他的経済水域', '国土面積が小さいのに排他的経済水域が広い国の組み合わせを選ぼう。\nア アメリカ合衆国とブラジル　イ インドネシアと日本　ウ ブラジルとアメリカ合衆国', T('イ'), 'インドネシアと日本は国土に比べて排他的経済水域がとても広い。', near=['ア', 'ウ'])
    q(17, 'D②(2)', '排他的経済水域', '日本やインドネシアが、国土面積に比べて排他的経済水域が広いのは、国土にどのような特徴があるからか。', R((1, ['島国', '島が多', '島々', '離島']),), 'どちらも島国で、周りに島が多くあるから。', example='どちらも島国だから。')
    q(29, 'その③(1)', '排他的経済水域', '国土面積が約38万km²、排他的経済水域（領海をふくむ）が約447万km²の日本では、排他的経済水域は国土面積の約何倍か。整数で答えよう。', N(12, ['倍']), '447÷38≒11.8→約12倍。', near=['11', '10'])
    # 端の島
