    q(10, '④', '日本の端', '日本の北端の島は何か。', T('択捉島', 'えとろふとう'), '北端は択捉島（北海道）。', near=['国後島', '色丹島'])
    q(11, '資料の活用', '沖ノ鳥島', '沖ノ鳥島で、波の侵食から島を守るために行われた工事を何というか。', T('護岸工事', 'ごがんこうじ'), '島の周りをコンクリートなどで固める護岸工事。', near=['埋め立て'])
    q(28, 'その②(3)', '沖ノ鳥島', '政府が沖ノ鳥島で護岸工事を行った理由を、「排他的経済水域」という語句を使って書こう。', R((1, ['排他的経済水域']), (1, ['なくな', '失', '守']), (1, ['水没', '沈', 'しず', '侵食', '島'])), '島が水没すると、周りの排他的経済水域がなくなってしまうから。', example='島が水没すると、排他的経済水域がなくなってしまうから。')
    q(16, 'C②(3)', '沖ノ鳥島', '沖ノ鳥島を中心に半径約370kmの円をえがくと、その面積はおよそ何万km²になるか。円周率を3.14とし、千の位を四捨五入して「万km²」の単位で答えよう。', N(43, ['万km2', '万km²', '万']), '370×370×3.14＝429866km²→約43万km²。', near=['42', '116'])
