    q(75, '地方区分', '地方区分', '日本を7つの地方に分けたとき、新潟県がふくまれる地方はどこか。', T('中部地方', '中部'), '新潟県は中部地方。', near=['東北地方', '関東地方'])
    q(75, '地方区分', '地方区分', '日本を7つの地方に分けたとき、三重県がふくまれる地方はどこか。', T('近畿地方', '近畿'), '三重県は近畿地方。', near=['中部地方'])
    q(75, '地方区分', '地方区分', '日本を7つの地方に分けたとき、山口県がふくまれる地方はどこか。', T('中国・四国地方', '中国四国地方', '中国地方'), '山口県は中国・四国地方（中国地方）。', near=['九州地方'])
